contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function: target to forward to and value that C should attempt to send
    function run(address target, uint value) public payable {
        require(true);

        // record before-values
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBal = address(c).balance;

        // perform the call and capture whether it reverted
        bool reverted;
        c.sendMoney(target, value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBal = address(c).balance;

        // General rule: sendMoney never decreases depositsCount; if it reverted then neither depositsCount nor balance changed
        assert(afterCount >= beforeCount && (reverted ? (afterCount == beforeCount && afterBal == beforeBal) : true));
    }

    receive() external payable {}
}

